import "timezone"

// ⚠️ CRITICAL: Use Asia/Bangkok timezone for accurate hourly windows
// Without this, 01:00 Thai time = 18:00 UTC, causing report misalignment
option location = timezone.location(name: "Asia/Bangkok")

option task = {name: "aggregate_hourly", every: 1h, offset: 5m}

// ===== Aggregate power metrics (mean) =====
from(bucket: "AI205_raw")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "energy_3phase")
  |> filter(fn: (r) => r._field == "power_active" or r._field == "power_factor" or r._field == "frequency")
  |> group(columns: ["_measurement", "_field", "device_id"])
  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)
  |> to(bucket: "AI205_hourly", org: "Ennergy")

// ===== Aggregate energy consumption per hour =====
// ⚠️ FIXED: Calculate (last - first) within each hour window
// The old approach (aggregateWindow → difference) didn't work because
// difference needs 2+ records but aggregateWindow gives only 1 per window

// Get first value of each hour
firstData = from(bucket: "AI205_raw")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "energy_3phase")
  |> filter(fn: (r) => r._field == "energy_total")
  |> group(columns: ["_measurement", "_field", "device_id"])
  |> aggregateWindow(every: 1h, fn: first, createEmpty: false)
  |> set(key: "_field", value: "energy_first")

// Get last value of each hour
lastData = from(bucket: "AI205_raw")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "energy_3phase")
  |> filter(fn: (r) => r._field == "energy_total")
  |> group(columns: ["_measurement", "_field", "device_id"])
  |> aggregateWindow(every: 1h, fn: last, createEmpty: false)
  |> set(key: "_field", value: "energy_last")

// Join and calculate consumption
join(tables: {first: firstData, last: lastData}, on: ["_time", "device_id"])
  |> map(fn: (r) => ({
      _time: r._time,
      _measurement: "energy_3phase",
      _field: "energy_consumed",
      device_id: r.device_id,
      _value: r._value_last - r._value_first,
      energy_start: r._value_first,
      energy_end: r._value_last,
  }))
  |> map(fn: (r) => ({
      r with
      quality: if r._value < 0.0 then "invalid"
               else if r._value == 0.0 then "estimated"
               else "measured"
  }))
  |> to(bucket: "AI205_hourly", org: "Ennergy")

// ===== Aggregate per-phase data =====
from(bucket: "AI205_raw")
  |> range(start: -1h)
  |> filter(fn: (r) => r._measurement == "energy_per_phase")
  |> group(columns: ["_measurement", "_field", "device_id", "phase"])
  |> aggregateWindow(every: 1h, fn: mean, createEmpty: false)
  |> to(bucket: "AI205_hourly", org: "Ennergy")
